<section class="panel"><h2>Attendance</h2><?php if(!$attendance): ?><p>No site attendance recorded.</p><?php endif ?><div class="table-wrap"><table><thead><tr><th>Assignment</th><th>Technician user</th><th>Check-in</th><th>Check-out</th><th>Location / manual exception</th></tr></thead><tbody><?php foreach($attendance as $a): ?><tr><td>#<?= (int)$a['assignment_id'] ?></td><td>#<?= (int)$a['technician_user_id'] ?></td><td><?= esc($a['checked_in_at']) ?></td><td><?= esc($a['checked_out_at']??'—') ?></td><td><?= $a['latitude']!==null?esc($a['latitude'].', '.$a['longitude']):esc($a['manual_reason']) ?></td></tr><?php endforeach ?></tbody></table></div></section>
<section class="panel"><h2>Service reports</h2><?php if(!$reports): ?><p>No service reports yet.</p><?php endif ?><?php foreach($reports as $r): ?><article class="notice"><h3>Report #<?= (int)$r['id'] ?> · Assignment #<?= (int)$r['assignment_id'] ?></h3><p class="pre-line"><?= esc($r['report']) ?></p><small>Technician user #<?= (int)$r['technician_user_id'] ?> · <?= esc($r['created_at']) ?></small></article><?php endforeach ?></section>
<section class="panel"><h2>Equipment issues</h2><?php if(!$issues): ?><p>No equipment issues reported.</p><?php endif ?><?php foreach($issues as $i): ?><article class="notice"><h3>Issue #<?= (int)$i['id'] ?> · Assignment #<?= (int)$i['assignment_id'] ?></h3><span class="badge"><?= esc($i['status']) ?></span><p class="pre-line"><?= esc($i['description']) ?></p><?php if($i['status']==='open'): ?><form action="<?= site_url('issues/'.$i['id'].'/resolve') ?>" method="post"><?= csrf_field() ?><button class="secondary" type="submit">Mark resolved</button></form><?php endif ?></article><?php endforeach ?></section>
<section class="panel"><h2>Latest 200 audit entries</h2><div class="table-wrap"><table><thead><tr><th>Time</th><th>Actor user</th><th>Action</th><th>Record</th><th>Summary</th></tr></thead><tbody><?php foreach($logs as $log): ?><tr><td><?= esc($log['created_at']) ?></td><td><?= esc($log['actor_user_id']??'Public registration') ?></td><td><?= esc($log['event']) ?></td><td><?= esc($log['entity']) ?> #<?= (int)$log['entity_id'] ?></td><td><?= esc($log['summary']) ?></td></tr><?php endforeach ?></tbody></table></div></section>
